CREATE OR REPLACE PROCEDURE p (a IN NUMBER, b OUT VARCHAR2) AS
x number := 0;
BEGIN
  IF a > 0 THEN
    b := 'pos; yes';
  ELSIF a = 0 THEN
    b := 'zero';
  ELSE
    b := 'neg';
  END IF;
  FOR i IN 1 .. 3 LOOP
    x := x + i;
  END LOOP;
  dbms_output.put_line('x = ' || x);
EXCEPTION
  WHEN others THEN raise;
END;

